//! P1b: BV-tree builders and helpers against the real DLL.
//!
//! The reference is `tests/p1b_probe.c` (built to `p1b_probe.exe`), which runs
//! `CAABBTree::Build`, `COBBTree::Build`, the principal-axes fit and the convex hull inside
//! `cryphysics_dedicate.dll` on a mesh file and prints the results as raw bits. The port prints
//! the same text, so the comparison is a plain text diff.
//!
//! | env | effect |
//! |---|---|
//! | none | synthetic cases compare against `tests/golden/p1b_*.trace` |
//! | `AAEMU_PHYS_P1B_PROBE=<p1b_probe.exe>` | goldens are regenerated by the DLL and must match |
//! | + `AAEMU_PHYS_BLESS=1` | mismatching / missing goldens are rewritten |
//! | + `AAEMU_PHYS_CGF_DIR=<dir>` | also every trimesh in the CGF corpus (no goldens written) |

use aaemu_physics::geometry::bvtree::fit::principal_axes;
use aaemu_physics::geometry::bvtree::hull::convex_hull;
use aaemu_physics::geometry::bvtree::select::{build_mesh_tree, MeshTree};
use aaemu_physics::geometry::bvtree::{AabbTree, BuildMesh, BvTree, MemReader, MemWriter, ObbTree};
use aaemu_physics::math::{Mat33, Vec3};
use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::process::Command;

mod p1b_common;
use p1b_common as corpus;

/// A mesh in the probe's file format.
#[derive(Clone, Debug)]
struct Mesh {
    v: Vec<Vec3>,
    idx: Vec<i32>,
}

impl Mesh {
    fn bytes(&self) -> Vec<u8> {
        let mut b = Vec::new();
        b.extend((self.v.len() as u32).to_le_bytes());
        b.extend(((self.idx.len() / 3) as u32).to_le_bytes());
        for p in &self.v {
            for c in [p.x, p.y, p.z] {
                b.extend(c.to_bits().to_le_bytes());
            }
        }
        for i in &self.idx {
            b.extend(i.to_le_bytes());
        }
        b
    }
}

fn idx_line(idx: &[i32]) -> String {
    let mut s = String::from("idx");
    for i in idx {
        let _ = write!(s, " {i}");
    }
    s
}

fn port_aabb(m: &Mesh, min_t: i32, max_t: i32, skip: f32, flat: bool, basis: Mat33) -> String {
    let mut idx = m.idx.clone();
    let mut t = AabbTree::new(min_t, max_t, skip, basis, flat);
    let cost = t.build(&mut BuildMesh {
        vertices: &m.v,
        indices: &mut idx,
        mats: None,
        foreign_idx: None,
        aux: None,
    });
    let s = dump_aabb(&t, cost);
    s + &idx_line(&idx) + "\n"
}

fn dump_aabb(t: &AabbTree, cost: f32) -> String {
    let mut s = String::new();
    let _ = writeln!(
        s,
        "aabb cost {:08x} nnodes {} alloc {}",
        cost.to_bits(),
        t.nodes.len(),
        t.n_nodes_alloc
    );
    s += "root";
    let mut w = vec![
        t.center.x, t.center.y, t.center.z, t.size.x, t.size.y, t.size.z,
    ];
    w.extend(t.basis.to_array());
    for f in w {
        let _ = write!(s, " {:08x}", f.to_bits());
    }
    let _ = writeln!(
        s,
        "\nfields {} {} {} {} {} {:08x}",
        t.oriented,
        t.split_axes,
        t.map_shift,
        t.max_tris_per_leaf,
        t.min_tris_per_side,
        t.max_skip_dim.to_bits()
    );
    let _ = writeln!(s, "maxleaf {}", t.max_leaf_tris);
    for (i, n) in t.nodes.iter().enumerate() {
        let b = n.bounds;
        let _ = writeln!(
            s,
            "node {i} {} {} {} {} {} {} {} {} {}",
            n.ichild, b[0], b[1], b[2], b[3], b[4], b[5], n.ntris, n.single_coll
        );
    }
    s += "map";
    for w in &t.tri_map {
        let _ = write!(s, " {w:08x}");
    }
    s + "\n"
}

fn port_obb(m: &Mesh, min_t: i32, max_t: i32, skip: f32) -> String {
    let mut idx = m.idx.clone();
    let mut t = ObbTree::new(min_t, max_t, skip);
    let cost = t.build(&mut BuildMesh {
        vertices: &m.v,
        indices: &mut idx,
        mats: None,
        foreign_idx: None,
        aux: None,
    });
    dump_obb(&t, cost) + &idx_line(&idx) + "\n"
}

fn dump_obb(t: &ObbTree, cost: f32) -> String {
    let mut s = String::new();
    let _ = writeln!(
        s,
        "obb cost {:08x} nnodes {} alloc {} maxleaf {} skip {:08x}",
        cost.to_bits(),
        t.nodes.len(),
        t.n_nodes_alloc,
        t.max_leaf_tris,
        t.max_skip_dim.to_bits()
    );
    for (i, n) in t.nodes.iter().enumerate() {
        let b = n.to_bytes();
        let _ = write!(s, "node {i}");
        for k in 0..18 {
            let _ = write!(
                s,
                " {:08x}",
                u32::from_le_bytes([b[4 * k], b[4 * k + 1], b[4 * k + 2], b[4 * k + 3]])
            );
        }
        s += "\n";
    }
    s += "leaf";
    for l in &t.tri_leaf {
        let _ = write!(s, " {l}");
    }
    s + "\n"
}

/// The `CTriMesh` constructor's tree choice ([`build_mesh_tree`]); the probe runs the real
/// constructor with flags | 0x20000 | 2 (no welding, indices used in place), which leaves the
/// arrays as given (no foreign ids without flag 8).
fn port_mesh(m: &Mesh, flags: u32, min_t: i32, max_t: i32, fac: f32) -> String {
    let flags = flags | 0x20000 | 2;
    let mut idx = m.idx.clone();
    // With flag 8 and no foreign ids the constructor creates identity ones (permuted by the
    // builds and restored with the winner).
    let mut fid: Vec<i32> = if flags & 8 != 0 {
        (0..(m.idx.len() / 3) as i32).collect()
    } else {
        Vec::new()
    };
    let (tree, out) = build_mesh_tree(
        &mut BuildMesh {
            vertices: &m.v,
            indices: &mut idx,
            mats: None,
            foreign_idx: if fid.is_empty() { None } else { Some(&mut fid) },
            aux: None,
        },
        flags,
        min_t,
        max_t,
        fac,
    );
    // +152 = flags & 0x10800F (minus 8 when the foreign ids were generated) | the tree bit.
    let mut s = format!("mesh flags {:08x}\n", (flags & 0x0010_8007) | (out & 0xE0));
    match &tree {
        Some(MeshTree::SingleBox(t)) => {
            let mut w = MemWriter::new();
            t.save(&mut w);
            let mut r = MemReader::new(&w.buf);
            s += "singlebox";
            for _ in 0..16 {
                let _ = write!(s, " {:08x}", r.u32().unwrap());
            }
            let _ = writeln!(s, " {} {}", t.n_prims, t.is_convex);
        }
        Some(MeshTree::Aabb(a)) => s += &dump_aabb(a, 0.0),
        Some(MeshTree::Obb(o)) => s += &dump_obb(o, 0.0),
        None => {}
    }
    s += &idx_line(&idx);
    s += "\nforeign";
    for f in &fid {
        let _ = write!(s, " {f}");
    }
    s + "\n"
}

fn port_fit(m: &Mesh) -> String {
    let pa = principal_axes(&m.v, &m.idx, (m.idx.len() / 3) as i32);
    let mut s = String::from("fit");
    for r in pa.axes {
        for x in r {
            let _ = write!(s, " {:016x}", x.to_bits());
        }
    }
    for x in pa.center {
        let _ = write!(s, " {:016x}", x.to_bits());
    }
    s + "\n"
}

fn port_hull(m: &Mesh) -> String {
    let tris = convex_hull(&m.v).unwrap_or_default();
    let mut s = format!("hull {}", tris.len());
    for t in &tris {
        for i in t {
            let _ = write!(s, " {i}");
        }
    }
    s + "\n"
}

/// The probe's node-1 bytes and internal AABB `single_coll` bytes are uninitialised memory in
/// the original; mask them on both sides before comparing.
fn mask(text: &str) -> String {
    let mut out = String::new();
    for line in text.lines() {
        let f: Vec<&str> = line.split(' ').collect();
        if f.first() == Some(&"node") && f.len() == 11 {
            // AABB: node i ichild b0..b5 ntris single
            let i: usize = f[1].parse().unwrap_or(0);
            if i == 1 {
                let _ = writeln!(out, "node 1 - - - - - - - {} -", f[9]);
                continue;
            }
            if f[9] == "0" {
                let mut g = f.clone();
                g[10] = "-";
                out += &g.join(" ");
                out += "\n";
                continue;
            }
        }
        if f.first() == Some(&"node") && f.get(1) == Some(&"1") && f.len() == 20 {
            // OBB node 1: only iParent (word 15) and ntris (word 17) are written.
            let _ = writeln!(out, "node 1 {} {}", f[17], f[19]);
            continue;
        }
        out += line;
        out += "\n";
    }
    out
}

fn probe() -> Option<PathBuf> {
    std::env::var_os("AAEMU_PHYS_P1B_PROBE").map(PathBuf::from)
}

fn tmp_dir() -> PathBuf {
    let d = std::env::temp_dir().join(format!("aaemu_p1b_{}", std::process::id()));
    let _ = std::fs::create_dir_all(&d);
    d
}

fn run_probe(exe: &Path, cmd: &str, m: &Mesh, args: &[String]) -> String {
    let f = tmp_dir().join(format!("{cmd}_{}.mesh", m.idx.len()));
    std::fs::write(&f, m.bytes()).unwrap();
    let out = Command::new(exe)
        .arg(cmd)
        .arg(&f)
        .args(args)
        .output()
        .expect("run p1b_probe");
    String::from_utf8_lossy(&out.stdout).replace("\r\n", "\n")
}

fn golden_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/golden")
        .join(format!("p1b_{name}.trace"))
}

/// Compares the port's text with the DLL's (live probe) or the golden.
fn check(name: &str, port: &str, live: impl FnOnce(&Path) -> String) {
    let gp = golden_path(name);
    let reference = if let Some(exe) = probe() {
        let r = live(&exe);
        let bless = std::env::var_os("AAEMU_PHYS_BLESS").is_some();
        if bless && std::fs::read_to_string(&gp).ok().as_deref() != Some(r.as_str()) {
            std::fs::write(&gp, &r).unwrap();
        } else if let Ok(g) = std::fs::read_to_string(&gp) {
            assert_eq!(
                mask(&g),
                mask(&r),
                "{name}: golden is stale (rerun with AAEMU_PHYS_BLESS=1)"
            );
        }
        r
    } else {
        match std::fs::read_to_string(&gp) {
            Ok(g) => g.replace("\r\n", "\n"),
            Err(_) => {
                eprintln!("p1b: no golden {} and no probe — skipped", gp.display());
                return;
            }
        }
    };
    let (a, b) = (mask(port), mask(&reference));
    if a != b {
        for (i, (x, y)) in a.lines().zip(b.lines()).enumerate() {
            if x != y {
                panic!("{name}: first difference at line {i}:\n port: {x}\n  dll: {y}");
            }
        }
        panic!(
            "{name}: line counts differ ({} vs {})",
            a.lines().count(),
            b.lines().count()
        );
    }
}

/// Deterministic test meshes.
fn lcg(seed: &mut u32) -> f32 {
    *seed = seed.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
    (*seed >> 8) as f32 / 16_777_216.0
}

/// A noisy ellipsoid-ish blob: `n` latitude × `2n` longitude rings.
fn blob(n: usize, seed: u32, scale: Vec3, rot: f32) -> Mesh {
    let mut s = seed;
    let mut v = Vec::new();
    let (c, sn) = (rot.cos(), rot.sin());
    for i in 0..=n {
        let th = std::f32::consts::PI * i as f32 / n as f32;
        for j in 0..2 * n {
            let ph = std::f32::consts::PI * j as f32 / n as f32;
            let r = 1.0 + 0.15 * (lcg(&mut s) - 0.5);
            let p = Vec3::new(
                th.sin() * ph.cos() * r * scale.x,
                th.sin() * ph.sin() * r * scale.y,
                th.cos() * r * scale.z,
            );
            v.push(
                Vec3::new(c * p.x - sn * p.y, sn * p.x + c * p.y, p.z) + Vec3::new(0.3, -1.2, 2.5),
            );
        }
    }
    let mut idx = Vec::new();
    let w = 2 * n;
    for i in 0..n {
        for j in 0..w {
            let a = (i * w + j) as i32;
            let b = (i * w + (j + 1) % w) as i32;
            let cc = ((i + 1) * w + j) as i32;
            let d = ((i + 1) * w + (j + 1) % w) as i32;
            idx.extend([a, cc, b, b, cc, d]);
        }
    }
    Mesh { v, idx }
}

/// Scattered boxes (a "building" with flat parts).
fn boxes(k: usize, seed: u32) -> Mesh {
    let mut s = seed;
    let mut m = Mesh {
        v: Vec::new(),
        idx: Vec::new(),
    };
    for _ in 0..k {
        let o = Vec3::new(lcg(&mut s) * 20.0, lcg(&mut s) * 8.0, lcg(&mut s) * 3.0);
        let e = Vec3::new(
            0.2 + lcg(&mut s) * 3.0,
            0.1 + lcg(&mut s) * 2.0,
            0.05 + lcg(&mut s),
        );
        let base = m.v.len() as i32;
        for i in 0..8 {
            m.v.push(
                o + Vec3::new(
                    if i & 1 == 0 { -e.x } else { e.x },
                    if i & 2 == 0 { -e.y } else { e.y },
                    if i & 4 == 0 { -e.z } else { e.z },
                ),
            );
        }
        for t in [
            0, 2, 1, 1, 2, 3, 4, 5, 6, 5, 7, 6, 0, 1, 4, 1, 5, 4, 2, 6, 3, 3, 6, 7, 0, 4, 2, 2, 4,
            6, 1, 3, 5, 3, 7, 5,
        ] {
            m.idx.push(base + t);
        }
    }
    m
}

fn cases() -> Vec<(&'static str, Mesh)> {
    vec![
        ("blob6", blob(6, 1, Vec3::new(1.0, 2.0, 0.5), 0.3)),
        ("blob12", blob(12, 7, Vec3::new(3.0, 1.0, 1.5), 1.1)),
        ("boxes20", boxes(20, 3)),
        ("boxes3", boxes(3, 9)),
    ]
}

#[test]
fn p1b_aabb_build_matches_dll() {
    for (name, m) in cases() {
        for (tag, min_t, max_t, skip, flat) in [
            ("a", 2, 4, 0.1f32, false),
            ("b", 1, 6, 10.0, true),
            ("c", 3, 3, 0.0, false),
        ] {
            if name == "blob12" && tag != "a" {
                continue;
            }
            let port = port_aabb(&m, min_t, max_t, skip, flat, Mat33::IDENTITY);
            let args = vec![
                min_t.to_string(),
                max_t.to_string(),
                format!("{skip}"),
                i32::from(flat).to_string(),
            ];
            check(&format!("aabb_{name}_{tag}"), &port, |exe| {
                run_probe(exe, "aabb", &m, &args)
            });
        }
    }
}

#[test]
fn p1b_obb_build_matches_dll() {
    for (name, m) in cases() {
        for (tag, min_t, max_t, skip) in [("a", 2, 4, 0.1f32), ("b", 1, 8, 10.0)] {
            if name == "blob12" && tag != "a" {
                continue;
            }
            let port = port_obb(&m, min_t, max_t, skip);
            let args = vec![min_t.to_string(), max_t.to_string(), format!("{skip}")];
            check(&format!("obb_{name}_{tag}"), &port, |exe| {
                run_probe(exe, "obb", &m, &args)
            });
        }
    }
}

#[test]
fn p1b_mesh_tree_choice_matches_dll() {
    // blob12 (576 triangles) is left to the direct builder tests to keep the goldens small.
    for (name, m) in cases().into_iter().filter(|(n, _)| *n != "blob12") {
        for (tag, flags, min_t, max_t, fac) in [
            ("aabb", 0x40u32, 2, 4, 1.0f32),
            ("pa", 0x4_0000, 2, 4, 1.0),
            ("obb", 0x20, 2, 4, 1.0),
            ("all", 0x4_0060, 2, 4, 1.0),
            ("all_obbcheap", 0x4_0060, 2, 4, 0.5),
            ("flat", 0x4440, 1, 3, 1.0),
            ("box", 0x80, 2, 4, 1.0),
            ("all_fid", 0x4_0068, 2, 5, 0.8),
            ("aabbs_fid", 0x4_0048, 1, 4, 1.0),
        ] {
            let port = port_mesh(&m, flags, min_t, max_t, fac);
            let args = vec![
                format!("{flags:#x}"),
                min_t.to_string(),
                max_t.to_string(),
                format!("{fac}"),
            ];
            check(&format!("mesh_{name}_{tag}"), &port, |exe| {
                run_probe(exe, "mesh", &m, &args)
            });
        }
    }
}

#[test]
fn p1b_fit_and_hull_match_dll() {
    for (name, m) in cases() {
        check(&format!("fit_{name}"), &port_fit(&m), |exe| {
            run_probe(exe, "fit", &m, &[])
        });
        check(&format!("hull_{name}"), &port_hull(&m), |exe| {
            run_probe(exe, "hull", &m, &[])
        });
    }
}

/// Every trimesh in `AAEMU_PHYS_CGF_DIR` (with its own vertices) rebuilt by the DLL and the
/// port with the stored tree's parameters (and the stored basis for AABB trees).
#[test]
fn p1b_corpus_builds_match_dll() {
    let (Some(exe), Some(dir)) = (probe(), std::env::var_os("AAEMU_PHYS_CGF_DIR")) else {
        eprintln!("p1b: corpus oracle needs AAEMU_PHYS_P1B_PROBE and AAEMU_PHYS_CGF_DIR — skipped");
        return;
    };
    let limit: usize = std::env::var("AAEMU_P1B_LIMIT")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(usize::MAX);
    let mut files = Vec::new();
    corpus::cgf_files(Path::new(&dir), &mut files);
    let (mut ok, mut bad) = (0usize, Vec::new());
    'files: for f in files {
        let Ok(data) = std::fs::read(&f) else {
            continue;
        };
        for (k, blob) in corpus::phys_blobs(&data).into_iter().enumerate() {
            let Some(mb) = corpus::parse_trimesh(&blob) else {
                continue;
            };
            let (Some(v), Some(idx)) = (mb.verts, mb.idx) else {
                continue;
            };
            let m = Mesh { v, idx };
            let n_tris = (m.idx.len() / 3) as i32;
            let mut r = aaemu_physics::geometry::bvtree::MemReader::new(&blob[mb.tree_off..]);
            let name = format!(
                "{}#{k}",
                f.file_name().unwrap_or_default().to_string_lossy()
            );
            let (port, dll) = match mb.tree_type {
                1 => {
                    let st = AabbTree::load(&mut r, n_tris).unwrap();
                    let rel = st.max_skip_dim / st.size.x.max(st.size.y).max(st.size.z);
                    let rel = [0.1f32, 10.0, 0.0]
                        .into_iter()
                        .min_by(|a, b| (a - rel).abs().total_cmp(&(b - rel).abs()))
                        .unwrap();
                    let port = port_aabb(
                        &m,
                        st.min_tris_per_side,
                        st.max_tris_per_leaf,
                        rel,
                        false,
                        st.basis,
                    );
                    let mut args = vec![
                        st.min_tris_per_side.to_string(),
                        st.max_tris_per_leaf.to_string(),
                        format!("{rel}"),
                        "0".into(),
                    ];
                    args.extend(
                        st.basis
                            .to_array()
                            .iter()
                            .map(|x| format!("{:08x}", x.to_bits())),
                    );
                    (port, run_probe(&exe, "aabb", &m, &args))
                }
                0 => {
                    let st = ObbTree::load(&mut r, n_tris).unwrap();
                    let s = st.nodes[0].size;
                    let rel = st.max_skip_dim / s.x.max(s.y).max(s.z);
                    let rel = [0.1f32, 10.0, 0.0]
                        .into_iter()
                        .min_by(|a, b| (a - rel).abs().total_cmp(&(b - rel).abs()))
                        .unwrap();
                    let port = port_obb(&m, st.min_tris_per_side, st.max_tris_per_leaf, rel);
                    let args = vec![
                        st.min_tris_per_side.to_string(),
                        st.max_tris_per_leaf.to_string(),
                        format!("{rel}"),
                    ];
                    (port, run_probe(&exe, "obb", &m, &args))
                }
                _ => continue,
            };
            let (a, b) = (mask(&port), mask(&dll));
            if a == b {
                ok += 1;
            } else {
                let first = a
                    .lines()
                    .zip(b.lines())
                    .enumerate()
                    .find(|(_, (x, y))| x != y);
                bad.push(format!(
                    "{name} type {}: {:?}",
                    mb.tree_type,
                    first.map(|(i, (x, y))| (
                        i,
                        x.chars().take(160).collect::<String>(),
                        y.chars().take(160).collect::<String>()
                    ))
                ));
            }
            if ok + bad.len() >= limit {
                break 'files;
            }
        }
    }
    eprintln!(
        "p1b corpus: {ok} builds identical to the DLL, {} differ",
        bad.len()
    );
    for b in bad.iter().take(10) {
        eprintln!("  {b}");
    }
    assert!(bad.is_empty());
}
